DO $$
DECLARE
    t   text;
    tbls text[] := ARRAY[
        'prophylaxis_screening',
        'prophylaxis_initiation',
        'prophylaxis_interruptions',
        'prep_followup_visit',
        'pep_followup_visit'
    ];
BEGIN
    FOREACH t IN ARRAY tbls LOOP
        IF EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_name = t
              AND column_name = 'archived'
              AND data_type IN ('integer','smallint','bigint','numeric')
        ) THEN
            EXECUTE format('ALTER TABLE %I ALTER COLUMN archived DROP DEFAULT', t);
            EXECUTE format('ALTER TABLE %I ALTER COLUMN archived TYPE boolean USING (COALESCE(archived, 0) <> 0)', t);
            EXECUTE format('ALTER TABLE %I ALTER COLUMN archived SET DEFAULT false', t);
            EXECUTE format('UPDATE %I SET archived = false WHERE archived IS NULL', t);
            EXECUTE format('ALTER TABLE %I ALTER COLUMN archived SET NOT NULL', t);
        END IF;
    END LOOP;
END $$;

