UPDATE prep_clinic SET regimen_id = NULL                        WHERE regimen_id = '0';
UPDATE prep_clinic SET regimen_id = 'PREP_REGIMEN_TDF_FTC'      WHERE regimen_id = '1';
UPDATE prep_clinic SET regimen_id = 'PREP_REGIMEN_TDF_3TC'      WHERE regimen_id = '2';
UPDATE prep_clinic SET regimen_id = 'PREP_REGIMEN_CABOTEGRAVIR' WHERE regimen_id = '3';
UPDATE prep_clinic SET regimen_id = 'PREP_REGIMEN_LENACAPAVIR'  WHERE regimen_id = '4';
UPDATE prep_clinic tgt
    SET regimen_id = bac.code
  FROM base_application_codeset bac
  WHERE tgt.regimen_id ~ '^[0-9]+$'
    AND bac.id::text = tgt.regimen_id
    AND bac.codeset_group IN ('PREP_REGIMEN','PEP_REGIMEN');

